CREATE TABLE sessions(hash TEXT PRIMARY KEY, owner TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('browser','sender')), expires INTEGER NOT NULL);
CREATE TABLE devices(id TEXT PRIMARY KEY,owner TEXT NOT NULL,name TEXT NOT NULL,hash TEXT NOT NULL UNIQUE,revoked INTEGER NOT NULL DEFAULT 0);
CREATE TABLE pairs(code TEXT PRIMARY KEY,poll TEXT NOT NULL UNIQUE,expires INTEGER NOT NULL,token TEXT);
CREATE TABLE oauth(state TEXT PRIMARY KEY,verifier TEXT NOT NULL,nonce TEXT NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE messages(id TEXT PRIMARY KEY,owner TEXT NOT NULL,device TEXT NOT NULL,text TEXT NOT NULL,audio TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'pending',done INTEGER NOT NULL DEFAULT 0,created INTEGER NOT NULL,idem TEXT NOT NULL,UNIQUE(owner,idem));
CREATE INDEX inbox ON messages(device,done,created);
CREATE TABLE audio(id TEXT PRIMARY KEY,owner TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE limits(id TEXT PRIMARY KEY,n INTEGER NOT NULL,expires INTEGER NOT NULL);
